class Main {
    public static void main(String[] args) {
        // 전체와 한 묶음의 크기를 보관해요.
        int breads = 17;
        int bundleSize = 5;
        // /는 몫, %는 남은 개수를 구해요.
        System.out.println(breads / bundleSize);
        System.out.println(breads % bundleSize);
    }
}
